import sys, json, re

with open('/tmp/weo_page.html', 'r') as f:
    data = f.read()

# Find JSON between __NEXT_DATA__ tags
match = re.search(r'__NEXT_DATA__.*?type=\"application/json\">(.*?)</script>', data)
if match:
    j = json.loads(match.group(1))
    props = j.get('props', {}).get('pageProps', {})
    print('Top-level pageProps keys:', list(props.keys()))

    route = props.get('layoutData', {}).get('sitecore', {}).get('route', {})
    print('Route keys:', list(route.keys()))

    placeholders = route.get('placeholders', {})
    print('Placeholder keys:', list(placeholders.keys()))

    # Recursively find anything that looks like data
    def find_data(obj, path='', depth=0):
        if depth > 8:
            return
        if isinstance(obj, dict):
            for k, v in obj.items():
                if any(term in str(k).lower() for term in ['ngdp', 'data', 'value', 'georgia', 'country', 'subject', 'weo']):
                    if isinstance(v, (str, int, float)):
                        print(f'{path}.{k} = {v}')
                    elif isinstance(v, list) and len(v) < 50:
                        print(f'{path}.{k} = (list len={len(v)})')
                    elif isinstance(v, dict):
                        print(f'{path}.{k} = (dict keys={list(v.keys())[:10]})')
                find_data(v, f'{path}.{k}', depth+1)
        elif isinstance(obj, list):
            for i, item in enumerate(obj[:5]):
                find_data(item, f'{path}[{i}]', depth+1)

    find_data(j)
else:
    print('No NEXT_DATA found')
    # Check if there's data elsewhere
    if 'NGDP' in data:
        print('Found NGDP in page!')
        for line in data.split('\\n'):
            if 'NGDP' in line:
                print(line[:200])
